const DIAS_SEMANA = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];

const LETTERHEAD_B64 = 'data:image/jpeg;base64,';

let letterheadImg = null;
function loadLetterhead(){
  return new Promise((resolve)=>{
    const img = new Image();
    img.onload = ()=>{ letterheadImg = img; resolve(img); };
    img.onerror = ()=> resolve(null);
    img.src = LETTERHEAD_B64;
  });
}
loadLetterhead();

const el = id => document.getElementById(id);

function todayMonthValue(){
  const d = new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
}
el('mesRef').value = todayMonthValue();

function getBreakMode(){
  return document.querySelector('input[name=breakMode]:checked').value;
}

function toggleVisibility(){
  el('globalBreakFields').style.display = (getBreakMode() === 'global') ? 'flex' : 'none';
  el('noteField').style.display = el('optNote').checked ? 'flex' : 'none';
  el('overtimeFields').style.display = el('optOvertime').checked ? 'flex' : 'none';
  el('paymentFields').style.display = el('optPayment').checked ? 'flex' : 'none';
  el('bancoFields').style.display = el('optBanco').checked ? 'flex' : 'none';
}

['optNote','optOvertime','optPayment','optBanco'].forEach(id=>{
  el(id).addEventListener('change', ()=>{ toggleVisibility(); buildTable(); });
});
document.querySelectorAll('input[name=breakMode]').forEach(r=>{
  r.addEventListener('change', ()=>{ toggleVisibility(); buildTable(); });
});
el('optHideWeekend').addEventListener('change', buildTable);
el('mesRef').addEventListener('change', buildTable);

function timeToMinutes(t){
  if(!t) return null;
  const [h,m] = t.split(':').map(Number);
  return h*60+m;
}

function minutesToHHMM(mins){
  if(mins == null || isNaN(mins)) mins = 0;
  const sign = mins < 0 ? '-' : '';
  mins = Math.abs(Math.round(mins));
  const h = Math.floor(mins/60);
  const m = mins % 60;
  return sign + String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0');
}

function formatClock(t){
  if(!t) return '';
  if(el('optFormat24h').checked) return t;
  let [h,m] = t.split(':').map(Number);
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12; if(h===0) h = 12;
  return h + ':' + String(m).padStart(2,'0') + ' ' + ampm;
}

function buildTable(){
  const [year, month] = el('mesRef').value.split('-').map(Number);
  const daysInMonth = new Date(year, month, 0).getDate();
  const hideWeekend = el('optHideWeekend').checked;
  const breakMode = getBreakMode();
  const overtime = el('optOvertime').checked;
  const banco = el('optBanco').checked;

  const thead = el('theadPonto');
  const tbody = el('tbodyPonto');

  let headCols = '<th>Dia</th><th>Feriado</th><th>Entrada</th>';
  if(breakMode === 'perday'){
    headCols += '<th>Saída almoço</th><th>Retorno almoço</th>';
  } else {
    headCols += '<th>Intervalo</th><th>Início</th><th>Fim</th>';
  }
  headCols += '<th>Saída</th><th>Horas</th>';
  if(overtime) headCols += '<th>Hora extra</th>';
  if(banco) headCols += '<th>Saldo</th>';
  thead.innerHTML = '<tr>'+headCols+'</tr>';

  const existing = {};
  tbody.querySelectorAll('tr').forEach(tr=>{
    const day = tr.dataset.day;
    const data = {};
    tr.querySelectorAll('[data-field]').forEach(fieldEl=>{
      data[fieldEl.dataset.field] = fieldEl.type === 'checkbox' ? fieldEl.checked : fieldEl.value;
    });
    existing[day] = data;
  });

  let rows = '';
  for(let d=1; d<=daysInMonth; d++){
    const dateObj = new Date(year, month-1, d);
    const wk = dateObj.getDay();
    const isWeekend = (wk===0 || wk===6);
    if(hideWeekend && isWeekend) continue;

    const prev = existing[d] || {};
    const isFeriado = !!prev.feriado;
    const entrada = prev.entrada || '';
    const saidaAlmoco = prev.saidaAlmoco || '';
    const retornoAlmoco = prev.retornoAlmoco || '';
    const saida = prev.saida || '';
    const intervaloExc = !!prev.intervaloExc;
    const intInicio = prev.intInicio || '';
    const intFim = prev.intFim || '';
    const dis = isFeriado ? 'disabled' : '';
    const intDis = (isFeriado || !intervaloExc) ? 'disabled' : '';

    let cols = `<td class="daycell">${String(d).padStart(2,'0')}<span class="wk">${DIAS_SEMANA[wk]}</span></td>`;
    cols += `<td class="feriado-cell"><input type="checkbox" data-field="feriado" ${isFeriado?'checked':''}></td>`;
    cols += `<td><input type="time" value="${entrada}" data-field="entrada" ${dis}></td>`;
    if(breakMode === 'perday'){
      cols += `<td><input type="time" value="${saidaAlmoco}" data-field="saidaAlmoco" ${dis}></td>`;
      cols += `<td><input type="time" value="${retornoAlmoco}" data-field="retornoAlmoco" ${dis}></td>`;
    } else {
      cols += `<td class="intervalo-cell"><input type="checkbox" data-field="intervaloExc" ${intervaloExc?'checked':''} ${dis}></td>`;
      cols += `<td><input type="time" value="${intInicio}" data-field="intInicio" ${intDis}></td>`;
      cols += `<td><input type="time" value="${intFim}" data-field="intFim" ${intDis}></td>`;
    }
    cols += `<td><input type="time" value="${saida}" data-field="saida" ${dis}></td>`;
    cols += `<td class="hours-cell" data-field="horas">00:00</td>`;
    if(overtime) cols += `<td class="extra-cell" data-field="extra">00:00</td>`;
    if(banco) cols += `<td class="saldo-cell" data-field="saldo">00:00</td>`;

    rows += `<tr data-day="${d}" class="${isWeekend?'weekend':''}${isFeriado?' holiday':''}">${cols}</tr>`;
  }
  tbody.innerHTML = rows;

  tbody.querySelectorAll('input[type=time]').forEach(inp=>{
    inp.addEventListener('change', calcular);
  });

  tbody.querySelectorAll('[data-field=feriado]').forEach(cb=>{
    cb.addEventListener('change', ()=>{
      const tr = cb.closest('tr');
      tr.classList.toggle('holiday', cb.checked);
      tr.querySelectorAll('input[type=time]').forEach(inp=>{
        inp.disabled = cb.checked;
        if(cb.checked) inp.value = '';
      });
      const intCb = tr.querySelector('[data-field=intervaloExc]');
      if(intCb){
        intCb.disabled = cb.checked;
        if(cb.checked) intCb.checked = false;
      }
      calcular();
    });
  });

  tbody.querySelectorAll('[data-field=intervaloExc]').forEach(cb=>{
    cb.addEventListener('change', ()=>{
      const tr = cb.closest('tr');
      tr.querySelectorAll('[data-field=intInicio],[data-field=intFim]').forEach(inp=>{
        inp.disabled = !cb.checked;
        if(!cb.checked) inp.value = '';
      });
      calcular();
    });
  });

  calcular();
}

function calcular(){
  const breakMode = getBreakMode();
  const overtime = el('optOvertime').checked;
  const payment = el('optPayment').checked;
  const banco = el('optBanco').checked;

  const gStart = timeToMinutes(el('globalBreakStart').value);
  const gEnd = timeToMinutes(el('globalBreakEnd').value);
  const threshold = parseFloat(el('overtimeThreshold').value) || 0;
  const multiplier = parseFloat(el('overtimeMultiplier').value) || 1;
  const valorHora = parseFloat(el('valorHora').value) || 0;
  const moeda = el('moeda').value || '';
  const cargaHoraria = parseFloat(el('cargaHoraria').value) || 0;

  let totalMin = 0, totalExtraMin = 0, totalRegularMin = 0, totalSaldoMin = 0;

  document.querySelectorAll('#tbodyPonto tr').forEach(tr=>{
    const isFeriado = tr.querySelector('[data-field=feriado]').checked;
    if(isFeriado){
      tr.querySelector('[data-field=horas]').textContent = 'Feriado';
      const extraCell = tr.querySelector('[data-field=extra]');
      if(extraCell) extraCell.textContent = '—';
      const saldoCell = tr.querySelector('[data-field=saldo]');
      if(saldoCell) saldoCell.textContent = '00:00';
      return;
    }

    const entrada = timeToMinutes(tr.querySelector('[data-field=entrada]').value);
    const saida = timeToMinutes(tr.querySelector('[data-field=saida]').value);
    let breakMin = 0;

    if(breakMode === 'global'){
      if(gStart!=null && gEnd!=null && gEnd > gStart) breakMin = gEnd - gStart;
    } else if(breakMode === 'perday'){
      const sa = timeToMinutes(tr.querySelector('[data-field=saidaAlmoco]').value);
      const ra = timeToMinutes(tr.querySelector('[data-field=retornoAlmoco]').value);
      if(sa!=null && ra!=null && ra > sa) breakMin = ra - sa;
    }
    // breakMode === 'none' → breakMin permanece 0

    if(breakMode !== 'perday'){
      const intervaloExcInput = tr.querySelector('[data-field=intervaloExc]');
      if(intervaloExcInput && intervaloExcInput.checked){
        const iStart = timeToMinutes(tr.querySelector('[data-field=intInicio]').value);
        const iEnd = timeToMinutes(tr.querySelector('[data-field=intFim]').value);
        breakMin = (iStart!=null && iEnd!=null && iEnd > iStart) ? (iEnd - iStart) : 0;
      }
    }

    let worked = 0;
    if(entrada!=null && saida!=null){
      let diff = saida - entrada;
      if(diff < 0) diff += 24*60;
      worked = Math.max(0, diff - breakMin);
    }

    tr.querySelector('[data-field=horas]').textContent = minutesToHHMM(worked);

    let regular = worked, extra = 0;
    if(overtime){
      const thresholdMin = threshold * 60;
      regular = Math.min(worked, thresholdMin);
      extra = Math.max(0, worked - thresholdMin);
      const extraCell = tr.querySelector('[data-field=extra]');
      if(extraCell) extraCell.textContent = minutesToHHMM(extra);
    }

    totalMin += worked;
    totalRegularMin += regular;
    totalExtraMin += extra;

    if(banco){
      const isWeekendRow = tr.classList.contains('weekend');
      const hasEntry = (entrada != null || saida != null);
      const expectedMin = (!isWeekendRow && hasEntry) ? cargaHoraria * 60 : 0;
      totalSaldoMin += (worked - expectedMin);
      const saldoCell = tr.querySelector('[data-field=saldo]');
      if(saldoCell) saldoCell.textContent = minutesToHHMM(worked - expectedMin);
    }
  });

  let html = '';
  html += `<div class="total-item"><div class="label">Total de horas</div><div class="value">${minutesToHHMM(totalMin)}</div></div>`;
  if(overtime){
    html += `<div class="total-item"><div class="label">Horas normais</div><div class="value">${minutesToHHMM(totalRegularMin)}</div></div>`;
    html += `<div class="total-item extra"><div class="label">Horas extras</div><div class="value">${minutesToHHMM(totalExtraMin)}</div></div>`;
  }
  if(payment){
    const totalPay = (totalRegularMin/60)*valorHora + (totalExtraMin/60)*valorHora*multiplier;
    html += `<div class="total-item pay"><div class="label">Pagamento estimado</div><div class="value">${moeda} ${totalPay.toFixed(2)}</div></div>`;
  }
  if(banco){
    const label = totalSaldoMin < 0 ? 'Horas devidas' : 'Banco de horas';
    const cssClass = totalSaldoMin < 0 ? 'total-item devido' : 'total-item banco';
    html += `<div class="${cssClass}"><div class="label">${label}</div><div class="value">${minutesToHHMM(Math.abs(totalSaldoMin))}</div></div>`;
  }

  el('totaisResumo').innerHTML = html;
}

el('btnCalcular').addEventListener('click', calcular);

el('btnReiniciar').addEventListener('click', ()=>{
  if(!confirm('Isso vai limpar todos os horários preenchidos e as opções. Continuar?')) return;
  el('nomePonto').value = '';
  el('mesRef').value = todayMonthValue();
  ['optHideWeekend','optNote','optOvertime','optPayment','optBanco'].forEach(id=> el(id).checked = false);
  el('optFormat24h').checked = true;
  el('breakModePerDay').checked = true;
  el('paperLetterhead').checked = true;
  el('notaTexto').value = '';
  el('globalBreakStart').value = '12:00';
  el('globalBreakEnd').value = '13:00';
  el('overtimeThreshold').value = 8;
  el('overtimeMultiplier').value = 1.5;
  el('moeda').value = 'R$';
  el('valorHora').value = 0;
  el('cargaHoraria').value = 8;
  toggleVisibility();
  buildTable();
});

el('btnPdf').addEventListener('click', async ()=>{
  const btn = el('btnPdf');
  const originalText = btn.textContent;
  btn.textContent = 'Gerando PDF...';
  btn.disabled = true;

  const useLetterhead = document.querySelector('input[name=paperStyle]:checked').value === 'letterhead';
  if(useLetterhead && !letterheadImg){
    await loadLetterhead();
  }

  const nome = el('nomePonto').value.trim() || 'ponto';
  const mesVal = el('mesRef').value;
  const [y,m] = mesVal.split('-').map(Number);
  const mesLabel = new Intl.DateTimeFormat('pt-BR', {month:'long', year:'numeric'}).format(new Date(y, m-1, 1));

  const printArea = document.createElement('div');
  printArea.style.background = '#fff';
  printArea.style.padding = '0';
  printArea.style.width = '1000px';
  printArea.style.fontFamily = "'Segoe UI', system-ui, Arial, sans-serif";

  const header = document.createElement('div');
  header.innerHTML = `
    <h1 style="color:#16324F;font-size:20px;margin:0 0 2px 0;">Ponto — ${nome || 'Sem nome'}</h1>
    <p style="color:#5C6B76;font-size:13px;margin:0 0 16px 0;text-transform:capitalize;">${mesLabel}</p>
  `;
  printArea.appendChild(header);

  const tableClone = document.getElementById('tabelaPonto').cloneNode(true);
  tableClone.style.width = '100%';
  printArea.appendChild(tableClone);

  const totalsClone = document.getElementById('totaisResumo').cloneNode(true);
  totalsClone.style.marginTop = '14px';
  totalsClone.style.paddingTop = '12px';
  totalsClone.style.borderTop = '1px solid #DCE3E9';
  totalsClone.style.display = 'flex';
  totalsClone.style.gap = '28px';
  printArea.appendChild(totalsClone);

  if(el('optNote').checked && el('notaTexto').value.trim()){
    const note = document.createElement('div');
    note.style.marginTop = '16px';
    note.style.padding = '10px 12px';
    note.style.background = '#FBF7EE';
    note.style.border = '1px solid #EFE3C6';
    note.style.borderRadius = '7px';
    note.style.fontSize = '13px';
    note.style.color = '#5C6B76';
    note.style.whiteSpace = 'pre-wrap';
    note.textContent = el('notaTexto').value;
    printArea.appendChild(note);
  }

  document.body.appendChild(printArea);

  try{
    const canvas = await html2canvas(printArea, {scale:2, backgroundColor:'#ffffff'});
    document.body.removeChild(printArea);

    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF('p','mm','a4');
    const pageWidth = 210;
    const pageHeight = 297;

    const marginLeft = useLetterhead ? 15 : 10;
    const marginTop = useLetterhead ? 42 : 10;
    const marginBottom = useLetterhead ? 25 : 10;

    const contentWidthMM = pageWidth - marginLeft*2;
    const usableHeightMM = pageHeight - marginTop - marginBottom;

    const pxPerMM = canvas.width / contentWidthMM;
    const pageSliceHeightPx = Math.floor(usableHeightMM * pxPerMM);

    const totalPages = Math.max(1, Math.ceil(canvas.height / pageSliceHeightPx));

    for(let page=0; page<totalPages; page++){
      if(page > 0) pdf.addPage();

      if(useLetterhead && letterheadImg){
        pdf.addImage(letterheadImg, 'JPEG', 0, 0, pageWidth, pageHeight);
      }

      const sy = page * pageSliceHeightPx;
      const sHeightPx = Math.min(pageSliceHeightPx, canvas.height - sy);

      const sliceCanvas = document.createElement('canvas');
      sliceCanvas.width = canvas.width;
      sliceCanvas.height = sHeightPx;
      const ctx = sliceCanvas.getContext('2d');
      ctx.drawImage(canvas, 0, sy, canvas.width, sHeightPx, 0, 0, canvas.width, sHeightPx);

      const sliceHeightMM = sHeightPx / pxPerMM;
      const sliceData = sliceCanvas.toDataURL('image/png');
      pdf.addImage(sliceData, 'PNG', marginLeft, marginTop, contentWidthMM, sliceHeightMM);
    }

    const safeNome = nome.replace(/[^a-zA-Z0-9À-ú _-]/g,'').trim().replace(/\s+/g,'_') || 'ponto';
    const safeMes = mesVal || 'mes';
    pdf.save(`${safeNome}_${safeMes}.pdf`);
  } catch(e){
    if(document.body.contains(printArea)) document.body.removeChild(printArea);
    alert('Não foi possível gerar o PDF: ' + e.message);
  } finally {
    btn.textContent = originalText;
    btn.disabled = false;
  }
});

toggleVisibility();
buildTable();
